# qx_color_hex_to_rgb :: '#FF0000'
def qx_color_hex_to_rgb(h):
    h = h.lstrip('#')
    if len(h) == 3: h = ''.join(c*2 for c in h)
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)

if __name__ == '__main__':
    print(qx_color_hex_to_rgb('#FF0000'))

